// frontend/src/user/components/RecentBlogPosts.jsx
import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';

const API_BASE = process.env.REACT_APP_API_BASE || "";

export default function RecentBlogPosts() {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // گرفتن ۳ مقاله آخر از API
    axios.get(`${API_BASE}/api/blog?limit=3`)
      .then(res => {
        setPosts(res.data.posts || []);
        setLoading(false);
      })
      .catch(err => {
        console.error("خطا در گرفتن مقالات:", err);
        setLoading(false);
      });
  }, []);

  // اگر مقاله‌ای وجود نداشت یا در حال لود بود، چیزی نشان نده (تا صفحه اصلی خالی به نظر نرسه)
  if (loading || posts.length === 0) return null;

  return (
    <section className="py-16 bg-miko-cream/50" dir="rtl">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        
        {/* هدر بخش */}
        <div className="flex items-center justify-between mb-8">
          <div>
            <h2 className="text-2xl sm:text-3xl font-black text-miko-dark mb-2 font-display">
              مجله میکو
            </h2>
            <p className="text-sm text-miko-dark/60">
              جدیدترین مقالات و نکات علمی درباره‌ی تغذیه و سلامت سگ‌ها
            </p>
          </div>
          <Link 
            to="/blog" 
            className="hidden sm:flex items-center gap-1 text-sm font-bold text-miko-rust hover:text-miko-pumpkin transition-colors"
          >
            مشاهده همه مقالات
            <span>←</span>
          </Link>
        </div>

        {/* گرید کارت‌ها */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {posts.map(post => (
            <Link 
              key={post.id} 
              to={`/blog/${post.slug}`}
              className="group bg-white rounded-2xl overflow-hidden shadow-sm border border-miko-carrot/20 hover:shadow-lg transition-all duration-300 flex flex-col"
            >
              {/* تصویر کارت */}
              <div className="relative h-48 w-full overflow-hidden bg-miko-carrot/10">
                {post.featured_image ? (
                  <img 
                    src={post.featured_image} 
                    alt={post.title}
                    className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                    loading="lazy"
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-miko-cream to-miko-carrot/30">
                    <span className="text-5xl">🐾</span>
                  </div>
                )}
                <div className="absolute top-3 right-3 bg-white/90 backdrop-blur-sm px-3 py-1 rounded-full text-xs font-bold text-miko-rust shadow-sm">
                  {post.category || 'عمومی'}
                </div>
              </div>

              {/* محتوای کارت */}
              <div className="p-5 flex flex-col flex-grow">
                <h3 className="text-lg font-bold text-miko-dark mb-2 line-clamp-2 group-hover:text-miko-rust transition-colors">
                  {post.title}
                </h3>
                <p className="text-sm text-miko-dark/60 line-clamp-3 mb-4 flex-grow">
                  {post.excerpt || "برای خواندن این مقاله کلیک کنید..."}
                </p>
                <div className="text-xs font-bold text-miko-rust flex items-center gap-1 mt-auto">
                  مطالعه مقاله
                  <span className="group-hover:-translate-x-1 transition-transform">←</span>
                </div>
              </div>
            </Link>
          ))}
        </div>

        {/* دکمه مشاهده همه در موبایل */}
        <div className="mt-8 text-center sm:hidden">
          <Link 
            to="/blog" 
            className="inline-block border-2 border-miko-rust text-miko-rust font-bold px-6 py-2.5 rounded-xl hover:bg-miko-rust hover:text-white transition-colors"
          >
            مشاهده همه مقالات
          </Link>
        </div>

      </div>
    </section>
  );
}